using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _envMock = new Mock<IWebHostEnvironment>();
            _envMock.Setup(e => e.WebRootPath).Returns((string)null);
            _envMock.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
            _loggerMock = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Department CreateTestDepartment(string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 9, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course CreateTestCourse(string title = "Chemistry", int credits = 3, int courseId = 1050)
        {
            var dept = _context.Departments.FirstOrDefault() ?? CreateTestDepartment();
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = credits,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // --- Index Tests ---

        [Fact]
        public void Index_ReturnsCoursesList()
        {
            CreateTestCourse("Math", 4, 1001);
            CreateTestCourse("Physics", 3, 1002);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_EmptyDatabase_ReturnsEmptyList()
        {
            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Empty(model);
        }

        // --- Details Tests ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var course = CreateTestCourse();

            var result = _controller.Details(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        // --- Create GET Tests ---

        [Fact]
        public void Create_Get_ReturnsViewWithEmptyCourse()
        {
            CreateTestDepartment();

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(0, model.CourseID);
        }

        // --- Create POST Tests ---

        [Fact]
        public void Create_Post_ValidCourse_RedirectsToIndex()
        {
            var dept = CreateTestDepartment();
            var course = new Course
            {
                CourseID = 2001,
                Title = "Literature",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            CreateTestDepartment();
            _controller.ModelState.AddModelError("Title", "Required");

            var course = new Course { CourseID = 2001, Credits = 3 };

            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Courses);
        }

