using System;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe"
            };

            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void Student_EnrollmentDate_CanBeSet()
        {
            var date = new DateTime(2023, 9, 1);
            var student = new Student { EnrollmentDate = date };

            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Student_Enrollments_CanBeInitialized()
        {
            var student = new Student
            {
                Enrollments = new System.Collections.Generic.List<Enrollment>()
            };

            Assert.NotNull(student.Enrollments);
            Assert.Empty(student.Enrollments);
        }

        [Fact]
        public void Instructor_HireDate_CanBeSet()
        {
            var date = new DateTime(2010, 3, 15);
            var instructor = new Instructor { HireDate = date };

            Assert.Equal(date, instructor.HireDate);
        }

        [Fact]
        public void Instructor_CourseAssignments_CanBeInitialized()
        {
            var instructor = new Instructor
            {
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };

            Assert.NotNull(instructor.CourseAssignments);
        }

        [Fact]
        public void Instructor_OfficeAssignment_CanBeSet()
        {
            var instructor = new Instructor
            {
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };

            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_Properties_CanBeSet()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/images/chem.jpg"
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/images/chem.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_NavigationProperties_CanBeSet()
        {
            var dept = new Department { Name = "Engineering" };
            var course = new Course
            {
                Department = dept,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };

            Assert.Equal(dept, course.Department);
            Assert.NotNull(course.Enrollments);
            Assert.NotNull(course.CourseAssignments);
        }
    }

    public class DepartmentTests
    {
        [Fact]
        public void Department_Properties_CanBeSet()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 5,
                RowVersion = new byte[] { 1, 2, 3 }
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
