namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional CoursesController tests targeting file upload and edge-case paths.
    /// </summary>
    public class CoursesControllerAdditionalTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;
        private readonly string _tempRoot;

        public CoursesControllerAdditionalTests()
        {
            _context = TestDbContextFactory.Create();
            _envMock = new Mock<IWebHostEnvironment>();
            _tempRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempRoot);
            _envMock.Setup(e => e.WebRootPath).Returns(_tempRoot);
            _envMock.Setup(e => e.ContentRootPath).Returns(_tempRoot);
            _loggerMock = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { Directory.Delete(_tempRoot, true); } catch { }
        }

        private Department CreateDepartment()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 100000m,
                StartDate = new DateTime(2020, 9, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course CreateCourse(int courseId = 3001)
        {
            var dept = _context.Departments.FirstOrDefault() ?? CreateDepartment();
            var course = new Course
            {
                CourseID = courseId,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        [Fact]
        public void Create_Post_ValidImageUpload_SavesFileAndRedirects()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 5001,
                Title = "Art",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var content = new byte[] { 0xFF, 0xD8, 0xFF }; // minimal JPEG header
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("material.jpg");
            fileMock.Setup(f => f.Length).Returns(content.Length);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = _context.Courses.Find(5001);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Edit_Post_ValidImageUpload_UpdatesImagePath()
        {
            var course = CreateCourse(5002);
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old.jpg";
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editCourse = new Course
            {
                CourseID = 5002,
                Title = "Updated",
                Credits = 4,
                DepartmentID = course.DepartmentID,
                TeachingMaterialImagePath = course.TeachingMaterialImagePath
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("new_image.png");
            fileMock.Setup(f => f.Length).Returns(2048);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(editCourse, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_OversizedFile_AddsModelError()
        {
            var course = CreateCourse(5003);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editCourse = new Course
            {
                CourseID = 5003,
                Title = "Test",
                Credits = 3,
                DepartmentID = course.DepartmentID
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("big.jpg");
            fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            var result = _controller.Edit(editCourse, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"].Errors.First().ErrorMessage);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImage_AttemptsFileDeletion()
        {
            var course = CreateCourse(5004);
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test.jpg";
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(5004) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Courses.Find(5004));
        }

        [Fact]
        public void DeleteConfirmed_CourseWithoutImage_Succeeds()
        {
            var course = CreateCourse(5005);
            course.TeachingMaterialImagePath = null;
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(5005) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_Post_FileUploadException_AddsModelError()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 5006,
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.jpg");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("Error uploading file", _controller.ModelState["teachingMaterialImage"].Errors.First().ErrorMessage);
        }

        [Fact]
        public void Edit_Post_FileUploadException_AddsModelError()
        {
            var course = CreateCourse(5007);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editCourse = new Course
            {
                CourseID = 5007,
                Title = "Test",
                Credits = 3,
                DepartmentID = course.DepartmentID
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.png");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Write error"));

            var result = _controller.Edit(editCourse, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_NullFile_UpdatesCourseWithoutImage()
        {
            var course = CreateCourse(5008);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editCourse = new Course
            {
                CourseID = 5008,
                Title = "Updated Title",
                Credits = 4,
                DepartmentID = course.DepartmentID
            };

            var result = _controller.Edit(editCourse, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_Post_ZeroLengthFile_SkipsUpload()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 5009,
                Title = "Art",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("empty.jpg");
            fileMock.Setup(f => f.Length).Returns(0);

            var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Courses.Find(5009).TeachingMaterialImagePath);
        }
    }
}

